<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{api,type ApiResponse,type OrderStatus,type ShopOrder}from'@whaashop/shared';
interface Item{id:number;productName:string;skuSpec:string;productImage?:string;unitPrice:number;quantity:number;reviewed:boolean}
const statusInfo:Record<OrderStatus,{label:string;hint:string;icon:string;step:number}>={PENDING_PAYMENT:{label:'待付款',hint:'请尽快完成支付',icon:'¥',step:0},PAID:{label:'待发货',hint:'商家正在准备商品',icon:'⌛',step:1},SHIPPED:{label:'待收货',hint:'商品已发出，请注意查收',icon:'▣',step:2},COMPLETED:{label:'已完成',hint:'感谢您的购买',icon:'✓',step:3},CLOSED:{label:'已关闭',hint:'订单已关闭',icon:'×',step:-1}};
const orders=ref<ShopOrder[]>([]),items=ref<Item[]>([]),dialog=ref(false),loading=ref(true),detailLoading=ref(false),selectedOrder=ref<ShopOrder>(),selected=ref<Item>(),review=reactive({rating:5,content:'',images:[]as string[]}),message=ref(''),error=ref('');
const detailTotal=computed(()=>items.value.reduce((sum,item)=>sum+Number(item.unitPrice)*item.quantity,0));
async function load(){loading.value=true;try{orders.value=(await api.get<ApiResponse<ShopOrder[]>>('/shop/orders')).data.data}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function confirm(o:ShopOrder){if(!window.confirm('确认已经收到商品吗？'))return;await api.post(`/shop/orders/${o.id}/confirm`);o.status='COMPLETED';if(selectedOrder.value?.id===o.id)selectedOrder.value.status='COMPLETED'}
async function detail(o:ShopOrder){selectedOrder.value=o;selected.value=undefined;message.value='';dialog.value=true;detailLoading.value=true;try{const data=(await api.get<ApiResponse<Item[]>>(`/shop/orders/${o.id}/items`)).data.data;items.value=data.map(item=>({...item,skuSpec:formatSpec(item.skuSpec)}))}catch(e){message.value=(e as Error).message}finally{detailLoading.value=false}}
function close(){dialog.value=false;selected.value=undefined;message.value=''}
async function pay(o:ShopOrder){const{data}=await api.post<ApiResponse<{formHtml?:string;redirectUrl?:string}>>(`/shop/orders/${o.id}/payment`);if(data.data.formHtml){const w=window.open('','_blank');w?.document.write(data.data.formHtml);w?.document.forms[0]?.submit()}else if(data.data.redirectUrl)window.open(data.data.redirectUrl,'_blank')}
function startReview(i:Item){selected.value=i;review.rating=5;review.content='';message.value=''}async function submitReview(){if(!selected.value)return;await api.post(`/shop/order-items/${selected.value.id}/reviews`,review);selected.value.reviewed=true;selected.value=undefined;message.value='评价发布成功'}
function date(value?:string){return value?new Date(value).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'--'}function money(value:number){return Number(value).toFixed(2)}
function formatSpec(value?:string){if(!value?.trim())return'默认规格';try{const parsed=JSON.parse(value);if(Array.isArray(parsed)){const parts=parsed.map(item=>item&&typeof item==='object'?Object.entries(item).map(([key,val])=>`${key}：${String(val)}`).join(' · '):String(item)).filter(Boolean);return parts.join(' · ')||'默认规格'}if(parsed&&typeof parsed==='object'){const parts=Object.entries(parsed).filter(([,val])=>val!==null&&val!==undefined&&String(val).trim()).map(([key,val])=>`${key}：${String(val)}`);return parts.join(' · ')||'默认规格'}return String(parsed)||'默认规格'}catch{return value}}
onMounted(load)
</script>

<template><div class="orders-page"><div class="container"><section class="orders-heading"><div><span>MY ORDERS</span><h1>我的订单</h1><p>查看订单进度，轻松管理每一次购物</p></div><div class="orders-count"><b>{{orders.length}}</b><small>全部订单</small></div></section><div v-if="loading" class="order-skeleton"><i v-for="n in 3" :key="n"></i></div><div v-else-if="error" class="orders-empty"><strong>订单加载失败</strong><p>{{error}}</p><button class="btn" @click="load">重新加载</button></div><div v-else-if="!orders.length" class="orders-empty"><span>▤</span><strong>还没有订单</strong><p>心仪好物正在商城等你发现</p><router-link class="btn" to="/">去逛逛</router-link></div><div v-else class="order-list"><article v-for="o in orders" :key="o.id" class="order-card"><div class="order-card-top"><div class="order-number"><span>{{statusInfo[o.status].icon}}</span><div><small>订单编号</small><b>{{o.orderNo}}</b></div></div><div class="order-status" :class="o.status.toLowerCase()"><b>{{statusInfo[o.status].label}}</b><small>{{statusInfo[o.status].hint}}</small></div></div><div class="order-card-body"><div class="order-meta"><div><small>下单时间</small><b>{{date(o.createdAt)}}</b></div><div><small>收货人</small><b>{{o.receiverName||'--'}}</b></div><div class="address"><small>收货地址</small><b>{{o.receiverAddress||'--'}}</b></div></div><div class="order-amount"><small>订单金额</small><b><i>¥</i>{{money(o.totalAmount)}}</b></div></div><div class="order-card-bottom"><span v-if="o.status==='SHIPPED'">商品正在配送途中，请收到商品后确认收货</span><span v-else>{{statusInfo[o.status].hint}}</span><div><button class="detail-button" @click="detail(o)">查看详情</button><button v-if="o.status==='PENDING_PAYMENT'" class="order-primary" @click="pay(o)">立即支付</button><button v-if="o.status==='SHIPPED'" class="order-primary" @click="confirm(o)">确认收货</button></div></div></article></div></div></div>

<Teleport to="body"><transition name="modal"><div v-if="dialog&&selectedOrder" class="order-modal-mask" @click.self="close"><section class="order-modal" role="dialog" aria-modal="true" aria-label="订单详情"><header><div><span>ORDER DETAILS</span><h2>订单详情</h2><p>订单号 {{selectedOrder.orderNo}}</p></div><button aria-label="关闭" @click="close">×</button></header><div class="order-modal-scroll"><div class="detail-status"><div class="detail-status-title"><span :class="selectedOrder.status.toLowerCase()">{{statusInfo[selectedOrder.status].icon}}</span><div><b>{{statusInfo[selectedOrder.status].label}}</b><small>{{statusInfo[selectedOrder.status].hint}}</small></div></div><div v-if="selectedOrder.status!=='CLOSED'" class="order-steps"><div v-for="(step,index) in ['提交订单','支付完成','商品发出','交易完成']" :key="step" :class="{done:statusInfo[selectedOrder.status].step>=index}"><i>{{statusInfo[selectedOrder.status].step>=index?'✓':index+1}}</i><span>{{step}}</span></div></div></div><section class="detail-section"><div class="detail-section-title"><h3>商品信息</h3><span>{{items.length}} 件商品</span></div><div v-if="detailLoading" class="detail-loading">正在加载商品…</div><article v-for="i in items" v-else :key="i.id" class="detail-product"><div class="detail-product-image"><img v-if="i.productImage" :src="i.productImage" :alt="i.productName"><span v-else>商品</span></div><div class="detail-product-info"><b>{{i.productName}}</b><span>{{i.skuSpec||'默认规格'}}</span><small>¥{{money(i.unitPrice)}} × {{i.quantity}}</small></div><strong>¥{{money(Number(i.unitPrice)*i.quantity)}}</strong><button v-if="selectedOrder.status==='COMPLETED'&&!i.reviewed" @click="startReview(i)">去评价</button><em v-else-if="i.reviewed">已评价</em></article></section><section class="detail-section detail-info"><h3>配送信息</h3><div><span>收货人</span><b>{{selectedOrder.receiverName||'--'}}</b><span>联系电话</span><b>{{selectedOrder.receiverPhone||'--'}}</b><span>收货地址</span><b>{{selectedOrder.receiverAddress||'--'}}</b><span>下单时间</span><b>{{date(selectedOrder.createdAt)}}</b><template v-if="selectedOrder.shippedAt"><span>发货时间</span><b>{{date(selectedOrder.shippedAt)}}</b></template></div></section><form v-if="selected" class="review-form" @submit.prevent="submitReview"><div><h3>评价 {{selected.productName}}</h3><button type="button" @click="selected=undefined">×</button></div><label>商品评分 <select v-model.number="review.rating"><option v-for="n in 5" :key="n" :value="n">{{n}} 星</option></select></label><textarea v-model="review.content" rows="4" maxlength="2000" required placeholder="分享你的真实使用感受…"></textarea><button class="order-primary">发布评价</button></form><p v-if="message" class="detail-message">{{message}}</p></div><footer><div><span>商品合计</span><small v-if="Math.abs(detailTotal-Number(selectedOrder.totalAmount))>.01">商品金额 ¥{{money(detailTotal)}}</small></div><strong>¥{{money(selectedOrder.totalAmount)}}</strong><button v-if="selectedOrder.status==='PENDING_PAYMENT'" class="order-primary" @click="pay(selectedOrder)">立即支付</button><button v-if="selectedOrder.status==='SHIPPED'" class="order-primary" @click="confirm(selectedOrder)">确认收货</button></footer></section></div></transition></Teleport></template>

